def meals():
    out = []
    for n in (78, 79, 80, 81):
        out.append('5:%d ' % n + '; '.join("'%s' ('%s', %s)" % (tr, ar, ', '.join(it)) for tr, ar, it in SEG[n]))
    return tuple(out)
